#include "preferences/beatdetectionsettings.h"

#include <gtest/gtest.h>

#include <QComboBox>
#include <QSignalSpy>

#include "analyzer/analyzerbeats.h"
#include "preferences/dialog/dlgprefbeats.h"
#include "test/mixxxtest.h"

class BeatDetectionSettingsTest : public MixxxTest {};

TEST_F(BeatDetectionSettingsTest, ExistingProfilesKeepTheirExplicitTempoAssumption) {
    BeatDetectionSettings settings(config());
    EXPECT_EQ(mixxx::BeatGridMode::Auto, settings.getTempoMode());
    settings.setFixedTempoAssumption(true);
    EXPECT_EQ(mixxx::BeatGridMode::Constant, settings.getTempoMode());
    settings.setFixedTempoAssumption(false);
    EXPECT_EQ(mixxx::BeatGridMode::Variable, settings.getTempoMode());
    settings.setTempoMode(mixxx::BeatGridMode::Auto);
    saveAndReloadConfig();
    EXPECT_EQ(mixxx::BeatGridMode::Auto, BeatDetectionSettings(config()).getTempoMode());
}

TEST_F(BeatDetectionSettingsTest, ModesPersistAndLegacySettersOverrideThem) {
    for (const auto mode : {mixxx::BeatGridMode::Auto,
                 mixxx::BeatGridMode::Constant,
                 mixxx::BeatGridMode::Variable}) {
        BeatDetectionSettings(config()).setTempoMode(mode);
        saveAndReloadConfig();
        EXPECT_EQ(mode, BeatDetectionSettings(config()).getTempoMode());
    }
    BeatDetectionSettings(config()).setFixedTempoAssumption(true);
    EXPECT_EQ(mixxx::BeatGridMode::Constant, BeatDetectionSettings(config()).getTempoMode());
    config()->setValue(ConfigKey(BPM_CONFIG_KEY, "tempo_mode"), 999);
    EXPECT_EQ(mixxx::BeatGridMode::Constant, BeatDetectionSettings(config()).getTempoMode());
}

TEST_F(BeatDetectionSettingsTest, DialogOffersOnlyExistingAnalyzersAndPersistsTempoModes) {
    DlgPrefBeats page(nullptr, config());
    ASSERT_EQ(2, page.comboBoxBeatPlugin->count());
    ASSERT_EQ(3, page.comboBoxTempoMode->count());
    for (const auto mode : {mixxx::BeatGridMode::Auto,
                 mixxx::BeatGridMode::Constant,
                 mixxx::BeatGridMode::Variable}) {
        page.comboBoxTempoMode->setCurrentIndex(
                page.comboBoxTempoMode->findData(static_cast<int>(mode)));
        EXPECT_EQ(mode == mixxx::BeatGridMode::Constant, page.checkBoxFastAnalysis->isEnabled());
        page.slotApply();
        EXPECT_EQ(mode, BeatDetectionSettings(config()).getTempoMode());
    }
    page.comboBoxBeatPlugin->setCurrentIndex(1);
    EXPECT_FALSE(page.comboBoxTempoMode->isEnabled());
}

TEST_F(BeatDetectionSettingsTest, RefreshDoesNotChangeSelectionsThroughSignals) {
    DlgPrefBeats page(nullptr, config());
    QSignalSpy pluginSpy(page.comboBoxBeatPlugin, &QComboBox::currentIndexChanged);
    QSignalSpy modeSpy(page.comboBoxTempoMode, &QComboBox::currentIndexChanged);
    BeatDetectionSettings(config()).setTempoMode(mixxx::BeatGridMode::Variable);
    page.slotUpdate();
    EXPECT_EQ(0, pluginSpy.count());
    EXPECT_EQ(0, modeSpy.count());
    EXPECT_EQ(static_cast<int>(mixxx::BeatGridMode::Variable),
            page.comboBoxTempoMode->currentData().toInt());
}
